use serde::{Serialize,Deserialize};
use serde_json::Value;
use base64::Engine as _;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use ed25519_dalek::Signer;
type ProtocolError = Box<dyn std::error::Error>;
pub fn canonical_json_bytes<T: Serialize>(value: &T) -> Result<Vec<u8>, ProtocolError> {
    Ok(serde_json_canonicalizer::to_vec(value)?)
}
pub fn encode_base64url(input: impl AsRef<[u8]>) -> String {
    URL_SAFE_NO_PAD.encode(input)
}
mod custody { use super::*; type Publication=Value; type MigrationPurpose=Value;
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]
#[serde(tag="operation",rename_all="snake_case",deny_unknown_fields)]
pub enum CustodyProofAction {
    Publish { publication: Box<Publication> },
    Register { prekey_bundle: Value },
    OpenSession,
    HomeMigration { control_hash: String, publication: Box<Publication>, purpose: MigrationPurpose },
}
pub fn framed_hash<T: Serialize>(tag: &str, value: &T) -> Result<String, ProtocolError> {
    let mut hash = blake3::Hasher::new();
    hash.update(tag.as_bytes());
    hash.update(&[0]);
    hash.update(&canonical_json_bytes(value)?);
    Ok(encode_base64url(hash.finalize().as_bytes()))
}
pub fn signing_bytes<T: Serialize>(tag: &str, body: &T) -> Result<Vec<u8>, ProtocolError> {
    #[derive(Serialize)]
    struct Transcript<'a, T> {
        domain: &'a str,
        body: &'a T,
    }
    canonical_json_bytes(&Transcript { domain: tag, body })
}
mod network {use super::*;
pub fn custody_action_hash(action: &CustodyProofAction) -> Result<String, crate::ProtocolError> {
    super::framed_hash("ramflux.identity.custody_action.v1", action)
}
} pub use network::custody_action_hash;
}
#[derive(Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DeviceRef {
    pub account_anchor: String,
    pub device_id: String,
    pub device_epoch: u64,
}
#[derive(Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BranchProofV3 {
    pub schema: String,
    pub version: u32,
    pub device_ref: DeviceRef,
    pub certificate_hash: String,
    pub record_hash: String,
    pub proof_id: String,
    pub challenge_nonce: String,
    pub action_hash: String,
    pub audience: String,
    pub binding_mode: BindingMode,
    pub transport_binding: String,
    pub issued_at: u64,
    pub expires_at: u64,
}
#[derive(Serialize,Deserialize)]
#[serde(rename_all="snake_case")]
pub enum BindingMode {
    DirectExporter,
    HomeRelayReceipt,
    NoChannelBinding,
}
fn main() -> Result<(),Box<dyn std::error::Error>> {
let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap())?)?;
let v=&input[0];
let action:custody::CustodyProofAction=serde_json::from_value(v["action"].clone())?;
let action_jcs=canonical_json_bytes(&action)?;
let hash=custody::custody_action_hash(&action)?;
let body:BranchProofV3=serde_json::from_value(v["proof_body"].clone())?;
let transcript=custody::signing_bytes("ramflux.identity.branch_proof.v3", &body)?;
let key=ed25519_dalek::SigningKey::from_bytes(&[14;32]);
let signature=key.sign(&transcript);
let hex=|data:&[u8]| data.iter().map(|b|format!("{b:02x}")).collect::<String>();
assert_eq!(hex(&action_jcs),v["action_jcs"].as_str().unwrap());
assert_eq!(hash,v["action_hash"].as_str().unwrap());
assert_eq!(hex(&transcript),v["proof_transcript"].as_str().unwrap());
assert_eq!(hex(&signature.to_bytes()),v["proof_signature"].as_str().unwrap());
println!("REGISTER_BASELINE PASS: pinned JCS/action hash/proof transcript/Dalek signature match"); Ok(()) }
